reaction.evaluate:
function evaluate(triggerType, triggerData, reactorToken, item, activationName, api) {
    const actor = reactorToken.actor;
    if (!actor) return false;

    const eligibleTypes = ["System", "Weapon"];

    return actor.itemTypes.npc_feature.some(
        (f) => f.system.destroyed && eligibleTypes.includes(f.system.type ?? ""),
    );
}

reaction.activationCode:
async function activation(triggerType, triggerData, reactorToken, item, activationName, api) {
    const actor = reactorToken.actor;
    if (!actor || !item) return;

    const eligibleTypes = ["System", "Weapon"];

    const destroyedItems = actor.itemTypes.npc_feature.filter(
        (f) => f.system.destroyed && eligibleTypes.includes(f.system.type ?? ""),
    );

    const chosenItem = await api.pickCard(destroyedItems, {
        description: "Choose a weapon or system to repair.",
        item,
        originToken: reactorToken,
        title: item.name,
    });
    if (!chosenItem) return;

    /** @type {Choices} */
    const choices = [];

    if (!api.hasStatus(reactorToken, "jammed")) {
        choices.push({
            callback() {
                return api.applyEffectsToTokens({
                    duration: { label: "start", turns: 1 },
                    effectNames: ["jammed"],
                    tokens: [reactorToken],
                });
            },
            text: "become Jammed",
        });
    }

    choices.push({
        callback() {
            return api.executeDamageRoll(reactorToken, [reactorToken], "1d6", "Heat", item.name);
        },
        text: "take 1d6 heat",
    });

    const result = await api.startChoiceCard({
        choices,
        description: `Choose how to repair "${chosenItem.name}"`,
        item,
        originToken: reactorToken,
        title: activationName,
    });
    if (!result) return;

    await chosenItem.update({ "system.destroyed": false });
}
